import { SendInvoiceEmail } from '../../setting/dto/update-settings.dto.js';
import { SettingsService } from '../../setting/settings.service.js';

export class PaymentEntity {
    private eventEmitter: EventEmitter;

    constructor() {
        this.eventEmitter = new EventEmitter();
    }

    publish(paymentProcessRequest: PaymentProcessRequest): PaymentResponse {
        // If there is a credit balance, first
        this.eventEmitter.emit(paymentProcessRequest.topic, paymentProcessRequest);
        return {
            message: 'Payment Event Published',
            id: randomUUID(),
            data: [paymentProcessRequest],
        };
    }
    subscribe(paymentChannel: paymentChannel, processor: PaymentProcessor) {
        this.eventEmitter.on(paymentChannel, processor.process);
    }
}

@Injectable()
export class StripePaymentProcessor extends EventEmitter implements PaymentProcessor {
    private static readonly logger = new Logger(StripePaymentProcessor.name);
    public creditService: CreditService;
    public taxService: TaxService;
    public paymentService: PaymentService;
    public localJWTAuthService: LocalJWTAuthService;
    public tokenConsumerService: TokenConsumerService;
    public settingsService: SettingsService;

    async process(paymentProcessRequest: PaymentProcessRequest) {
        try {
            const { paidAmount, chargeResponse } = await this.processPayment(paymentProcessRequest);
            const [{ invoice, businessID }] = paymentProcessRequest.data;
            const { sendInvoiceEmail } = await this.settingsService.findLatestSetting({ businessID });
            if (sendInvoiceEmail === SendInvoiceEmail.send) {
                CustomerService.customerCommunicationSystem.publish({
                    topic: CustomerCommunicationChannel.EMAIL,
                    data: [{ ...(await invoice.draftEmail(paidAmount, this.localJWTAuthService)), html: true }],
                    message: 'Sending email to customer',
                });
            }

            return chargeResponse;
        } catch (e) {
            StripePaymentProcessor.logger.error(
                `Input: ${JSON.stringify(paymentProcessRequest ? paymentProcessRequest : {})})}`,
            );
            StripePaymentProcessor.logger.error(serializeError(e));
            AuditService.publishEvent({
                topic: AuditScope.ERROR,
                message: 'Failed to process stripe payment',
                data: [{ error: serializeError(e) }],
            });
        }
    }

    private async processPayment({ data }: PaymentProcessRequest) {
        const [{ invoice, businessID, stripeAccountId, stripeCustomerId, accountState, customerId }] = data;
        const { totalAmountWithoutTax, taxAmount, currency } = invoice;
        if (!stripeAccountId) {
            return { paidAmount: 0 };
        }
        const { balance } = await this.creditService.findCreditBalance({ customerId, businessID });
        const creditBalance = parseFloat(balance);
        let payableTotal = invoice.total;
        invoice.payments = invoice?.payments || [];
        if (creditBalance > 0) {
            const timestamp = new Date().toISOString();
            if (creditBalance >= invoice.total) {
                StripePaymentProcessor.logger.log(
                    `Customer has a credit balance of ${creditBalance} and the invoice total is ${
                        totalAmountWithoutTax + taxAmount
                    }. The customer will be charged with the credit balance and the invoice will be marked as paid.`,
                );
                const { transactionRow } = await this.creditService.create({
                    customerId,
                    businessID,
                    transactionAmount: (invoice.total * -1).toFixed(2),
                    metadata: {
                        invoiceId: invoice.invoiceId,
                        reason: `Payment for ${invoice.invoiceId}`,
                    },
                });
                await this.paymentService.createAmountPaidTransaction({
                    transactionAmount: invoice.total,
                    metadata: {
                        paymentType: PaymentTypes.CREDIT,
                    },
                    invoiceId: invoice.invoiceId,
                    businessID,
                    timestamp,
                    customerId,
                });
                invoice.payments.push(new ReadPaymentDto(transactionRow));
                invoice.amountPaid = invoice.total;
                await StripePaymentProcessor.onSuccess({ data, topic: paymentChannel.Stripe });
                return { paidAmount: invoice.total };
            } else {
                StripePaymentProcessor.logger.log(
                    `Customer has a credit balance of ${creditBalance} and the invoice total is ${
                        totalAmountWithoutTax + taxAmount
                    }. The customer will be charged with the credit balance and the invoice will be marked as partially paid.`,
                );
                const { transactionRow } = await this.creditService.create({
                    customerId,
                    businessID,
                    timestamp,
                    transactionAmount: (creditBalance * -1).toFixed(2),
                    metadata: {
                        invoiceId: invoice.invoiceId,
                        reason: `Payment for ${invoice.invoiceId}`,
                    },
                });
                await this.paymentService.createAmountPaidTransaction({
                    transactionAmount: creditBalance,
                    metadata: {
                        paymentType: PaymentTypes.CREDIT,
                    },
                    invoiceId: invoice.invoiceId,
                    businessID,
                    timestamp,
                    customerId,
                });
                invoice.payments.push(new ReadPaymentDto(transactionRow));
                payableTotal = totalAmountWithoutTax + taxAmount - creditBalance;
            }
        }
        StripePaymentProcessor.logger.log(
            `Creating stripe payment with the following data: amount: ${
                totalAmountWithoutTax + taxAmount
            } currency: ${currency} customer: ${stripeCustomerId} stripeAccountId: ${stripeAccountId}`,
        );
        if (payableTotal) {
            try {
                const paymentIntentResponse: Stripe.Response<Stripe.PaymentIntent> =
                    await StripePaymentProcessor.stripePayment({
                        amount: parseInt(StripePaymentProcessor.calculateStripeTotal(payableTotal).toFixed(0)),
                        currency: currency
                            ? StripePaymentProcessor.convertToStripeCurrency(currency)
                            : StripePaymentProcessor.convertToStripeCurrency(SupportedCurrencies.USD),
                        businessID,
                        stripeCustomerId,
                        stripeAccountId,
                        accountState,
                        invoiceId: invoice.invoiceId,
                    });
                console.log(JSON.stringify(paymentIntentResponse));
                const stripePaidTimestamp = new Date().toISOString();
                await this.paymentService.createAmountPaidTransaction({
                    transactionAmount: payableTotal,
                    metadata: {
                        paymentIntentId: paymentIntentResponse?.id,
                        paymentType: PaymentTypes.STRIPE,
                    },
                    invoiceId: invoice.invoiceId,
                    businessID,
                    timestamp: stripePaidTimestamp,
                    customerId,
                });
                const {
                    amount,
                    id,
                    metadata,
                    currency: stripeCurrency,
                    status,
                    created,
                    charges,
                } = paymentIntentResponse;
                invoice.payments.push(
                    new ReadPaymentDto({
                        amount: amount && amount.toString(),
                        metadata,
                        currency: stripeCurrency,
                        status,
                        created: created && new Date(created).toISOString(),
                        paymentIntentsId: id,
                        charges: charges
                            ? charges.data.map((charge) => {
                                  return {
                                      chargeId: id,
                                      amount: StripePaymentProcessor.convertStripeAmountToPaigo(charge.amount),
                                  };
                              })
                            : [],
                    }),
                );

                invoice.amountPaid = invoice.total;
                await StripePaymentProcessor.onSuccess(
                    { data, topic: paymentChannel.Stripe },
                    paymentIntentResponse?.id,
                    this.taxService,
                );
                return { paidAmount: invoice.total, chargeResponse: paymentIntentResponse };
            } catch (error) {
                StripePaymentProcessor.logger.error(serializeError(error));
                await StripePaymentProcessor.onFailure({ data, topic: paymentChannel.Stripe }, error);
                return { paidAmount: invoice.total - payableTotal };
            }
        } else {
            StripePaymentProcessor.logger.log(`Payable total is zero, no payment will be processed`);
            return { paidAmount: 0 };
        }
    }

    static async processStripeRefund({
        amount,
        stripeAccountId,
        accountState,
        reason,
        paymentIntentId,
        chargeId,
    }: StripeRefundInput) {
        const stripe = new Stripe(
            accountState === AccountState.production ? process.env.PROD_STRIPE_TOKEN : process.env.STRIPE_TOKEN,
            { apiVersion: '2022-08-01' },
        );
        const { metadata } = await stripe.paymentIntents.retrieve(paymentIntentId, { stripeAccount: stripeAccountId });
        const refundResponse = await stripe.refunds.create(
            {
                amount: amount ? StripePaymentProcessor.calculateStripeTotal(parseFloat(amount)) : undefined,
                reason: reason as Stripe.RefundCreateParams.Reason,
                payment_intent: paymentIntentId,
                charge: chargeId,
                metadata: {
                    invoiceId: metadata?.invoiceId,
                },
            },
            { stripeAccount: stripeAccountId },
        );
        const { id } = refundResponse;
        return { refundId: id };
    }
    static async getRefundsForCustomer({
        stripeCustomerId,
        stripeAccountId,
        accountState,
    }): Promise<StripeRefundResponseDto[]> {
        const stripe = new Stripe(
            accountState === AccountState.production ? process.env.PROD_STRIPE_TOKEN : process.env.STRIPE_TOKEN,
            { apiVersion: '2022-08-01' },
        );
        let next_page;
        const refundsArray: Stripe.Charge[] = [];
        do {
            const refunds = await stripe.charges.search(
                { query: `customer:\"${stripeCustomerId}\" AND refunded:\"true\"`, limit: 100 },
                { stripeAccount: stripeAccountId },
            );
            if (refunds?.data?.length > 0) {
                refundsArray.push(...refunds.data);
            }

            if (refunds.has_more) {
                next_page = refunds.next_page;
            } else {
                next_page = null;
            }
        } while (next_page);

        do {
            const refunds = await stripe.charges.search(
                { query: `customer:\"${stripeCustomerId}\" AND refunded:\"false\"`, limit: 100 },
                { stripeAccount: stripeAccountId },
            );
            if (refunds?.data?.length > 0) {
                refundsArray.push(...refunds.data);
            }

            if (refunds.has_more) {
                next_page = refunds.next_page;
            } else {
                next_page = null;
            }
        } while (next_page);
        // Determine if we need to paginate the stripe search api response
        return refundsArray.map(({ amount_refunded, amount, id, metadata, currency, status, created }) => ({
            amountRefunded: StripePaymentProcessor.convertStripeAmountToPaigo(amount_refunded),
            amount: StripePaymentProcessor.convertStripeAmountToPaigo(amount),
            chargeId: id,
            metadata,
            currency,
            status,
            created: created ? new Date(created * 1000).toISOString() : undefined,
        }));
    }
    static convertStripeAmountToPaigo(amount: number): string {
        return (amount / 100).toFixed(2);
    }
    static async getPaymentsForCustomer({
        stripeCustomerId,
        stripeAccountId,
        accountState,
        metadata,
    }: {
        stripeCustomerId: string;
        stripeAccountId: string;
        accountState: AccountState;
        metadata?: { invoiceId: string };
    }): Promise<StripePaymentResponseDto[]> {
        StripePaymentProcessor.logger.debug(
            `Starting execution for getting payments for customer ${stripeCustomerId}, metadata: ${JSON.stringify(
                metadata ? metadata : {},
            )}`,
        );
        const stripe = new Stripe(
            accountState === AccountState.production ? process.env.PROD_STRIPE_TOKEN : process.env.STRIPE_TOKEN,
            { apiVersion: '2022-08-01' },
        );
        let next_page;
        const paymentsArray: Stripe.PaymentIntent[] = [];
        let query;
        StripePaymentProcessor.logger.debug(`metadata invoiceId: ${metadata?.invoiceId}`);
        if (metadata && metadata.invoiceId) {
            query = `customer:"${stripeCustomerId}" AND metadata[\'invoiceId\']:\'${metadata.invoiceId}\'`;
        } else {
            query = `customer:"${stripeCustomerId}"`;
        }
        StripePaymentProcessor.logger.debug(`query: ${query}`);
        do {
            const payments = await stripe.paymentIntents.search(
                { query: `customer:"${stripeCustomerId}"`, limit: 100 },
                { stripeAccount: stripeAccountId },
            );
            paymentsArray.push(...payments.data);

            if (payments.has_more) {
                next_page = payments.next_page;
            } else {
                next_page = null;
            }
        } while (next_page);
        // Determine if we need to paginate the stripe search api response
        return paymentsArray.map(({ amount, id, metadata, currency, charges, status, created }) => ({
            amount: StripePaymentProcessor.convertStripeAmountToPaigo(amount),
            paymentIntentsId: id,
            metadata,
            currency,
            charges: charges
                ? charges.data.map(({ id, amount: chargeAmount }) => ({
                      chargeId: id,
                      amount: StripePaymentProcessor.convertStripeAmountToPaigo(chargeAmount),
                  }))
                : [],
            status,
            created: created ? new Date(created * 1000).toISOString() : undefined,
        }));
    }
    static async onSuccess(
        paymentRequest: PaymentProcessRequest,
        paymentIntentId?: string,
        taxService?: TaxService,
        tokenConsumerService?: TokenConsumerService,
    ) {
        StripePaymentProcessor.logger.log('Payment was successful');
        // Update Invoice Status to Paid
        const {
            data: [{ invoice, businessID }],
        } = paymentRequest;
        invoice.invoiceStatus = InvoiceStatus.PAID;
        await invoice.saveToDB();
        WebhookPublishingService.publishEvent({
            topic: WebhookProcessorEventType.Standard,
            type: WebhookType.INVOICE_PAID,
            data: [new ReadInvoicesDto(invoice)],
            businessID,
        });
        try {
            StripePaymentProcessor.logger.log(
                `Logging token for payment: ${paymentRequest?.data[0]?.invoice?.invoiceId}`,
            );
            await tokenConsumerService.create({
                businessID: paymentRequest.data[0].businessID,
                tokenAmount: '1',
                metadata: {
                    tokenType: TokenType.payment,
                    invoiceId: paymentRequest.data[0].invoice.invoiceId,
                    paymentIntentId,
                    paymentChannel: 'stripe',
                },
                timestamp: new Date().toISOString(),
            });
        } catch (e) {
            StripePaymentProcessor.logger.error('Failed to log token for payment', serializeError(e));
            AuditService.publishEvent({
                topic: AuditScope.ERROR,
                message: 'Failed to log token for payment',
                data: [serializeError(e)],
            });
        }
        if (taxService) {
            await invoice.registerInvoiceTaxTransaction({ taxService: taxService, taxTransactionId: paymentIntentId });
        }
    }

    static async onFailure(paymentRequest: PaymentProcessRequest, error) {
        StripePaymentProcessor.logger.warn(
            `Payment was unsuccessful: InvoiceId: ${paymentRequest?.data[0]?.invoice?.invoiceId}  BusinessId: ${paymentRequest?.data[0]?.businessID} customerId: ${paymentRequest?.data[0]?.stripeCustomerId} stripeAccountId: ${paymentRequest?.data[0]?.stripeAccountId}`,
        );
        StripePaymentProcessor.logger.error(error);
    }
    static convertToStripeCurrency(argumentCurrency: SupportedCurrencies) {
        if (argumentCurrency === SupportedCurrencies.USD) {
            return currency.usd;
        }
        if (argumentCurrency === SupportedCurrencies.EUR) {
            return currency.eur;
        }
        if (argumentCurrency === SupportedCurrencies.CNY) {
            return currency.cny;
        } else {
            throw new Error('Currency not supported');
        }
    }
    static calculateStripeTotal(payableTotal: number) {
        return payableTotal * 100; // Convert to cents
    }

    public static async stripePayment({
        amount,
        currency,
        stripeCustomerId,
        stripeAccountId,
        accountState,
        invoiceId,
    }: StripePaymentDto): Promise<Stripe.Response<Stripe.PaymentIntent>> {
        const stripe = new Stripe(
            accountState === AccountState.production ? process.env.PROD_STRIPE_TOKEN : process.env.STRIPE_TOKEN,
            { apiVersion: '2022-08-01' },
        );
        const paymentMethods = await stripe.customers.listPaymentMethods(
            stripeCustomerId,
            {
                type: 'card',
            },
            { stripeAccount: stripeAccountId },
        );
        let customerPaymentMethod;
        if (paymentMethods) {
            const { data } = paymentMethods;
            if (data.length) {
                customerPaymentMethod = data[0].id;
            }
        }
        const charge = await stripe.paymentIntents.create(
            {
                amount,
                currency,
                customer: stripeCustomerId,
                payment_method: customerPaymentMethod,
                confirm: true,
                metadata: {
                    invoiceId: invoiceId ? invoiceId : undefined,
                    processedByPaigo: 'true',
                },
            },
            {
                stripeAccount: stripeAccountId,
            },
        );

        return charge;
    }

    public static async getStripeSession({
        sessionId,
        stripeAccountId,
        accountState,
    }: {
        sessionId: string;
        stripeAccountId: string;
        accountState: AccountState;
    }): Promise<Stripe.Response<Stripe.Checkout.Session>> {
        const stripe = new Stripe(
            accountState === AccountState.production ? process.env.PROD_STRIPE_TOKEN : process.env.STRIPE_TOKEN,
            { apiVersion: '2022-08-01' },
        );
        return stripe.checkout.sessions.retrieve(
            sessionId,
            { expand: ['payment_intent'] },
            {
                stripeAccount: stripeAccountId,
            },
        );
    }
}

export class ManualPaymentProcessor extends EventEmitter implements PaymentProcessor {
    private static readonly logger = new Logger(ManualPaymentProcessor.name);
    public paymentService: PaymentService;
    public localJWTAuthService: LocalJWTAuthService;
    public settingsService: SettingsService;
    async process(paymentRequest: PaymentProcessRequest) {
        try {
            const [{ invoice, businessID, customerId }] = paymentRequest.data;
            if (invoice?.invoiceStatus === InvoiceStatus.PAID) {
                await this.paymentService.createAmountPaidTransaction({
                    transactionAmount: invoice.total,
                    metadata: {
                        paymentType: PaymentTypes.MANUAL,
                    },
                    invoiceId: invoice.invoiceId,
                    businessID,
                    timestamp: new Date().toISOString(),
                    customerId,
                });
                await invoice.saveToDB();
                WebhookPublishingService.publishEvent({
                    topic: WebhookProcessorEventType.Standard,
                    type: WebhookType.INVOICE_PAID,
                    data: [new ReadInvoicesDto(invoice)],
                    businessID,
                });
                await invoice.generatePDFforInvoice({
                    fromEntity: invoice.fromEntity,
                    toEntity: invoice.toEntity,
                    regenerateInvoicePdf: true,
                    paidAmount: invoice.total,
                    jwtService: this.localJWTAuthService,
                });
            }
            if (invoice?.invoiceStatus === InvoiceStatus.OPEN) {
                const { sendInvoiceEmail } = await this.settingsService.findLatestSetting({ businessID });
                if (sendInvoiceEmail === SendInvoiceEmail.send) {
                    CustomerService.customerCommunicationSystem.publish({
                        topic: CustomerCommunicationChannel.EMAIL,
                        data: [{ ...(await invoice.draftEmail(0, this.localJWTAuthService)), html: true }],
                        message: 'Sending email to customer',
                    });
                }
            }
        } catch (e) {
            ManualPaymentProcessor.logger.error(`Input: ${JSON.stringify(paymentRequest ? paymentRequest : {})})}`);
            ManualPaymentProcessor.logger.error(serializeError(e));
            AuditService.publishEvent({
                topic: AuditScope.ERROR,
                message: 'Failed to process manual payment',
                data: [{ error: serializeError(e) }],
            });
        }
    }
}

import { Inject, Logger, forwardRef } from '@nestjs/common';
import { InfluxService } from '../influx/influx.service.js';
import { InvoicesService } from '../invoice/invoices.service.js';
import { Billing, billingScheduleConsumers } from './entities/billing.entity.js';
import { randomUUID } from 'crypto';
import { Process, Processor } from '@nestjs/bull';
import { CreateBillingReportDto } from './dto/createBillingReport.dto.js';
import { Job } from 'bull';
import { SchedulerEntity } from '../scheduler/entities/scheduler.entity.js';
import { CustomerService } from '../customer/customer.service.js';
import { AuditService } from '../audit/audit.service.js';
import { AuditScope } from '../audit/entities/audit.interface.js';
import { serializeError } from 'serialize-error';
import { SchedulerService } from '../scheduler/scheduler.service.js';
import { SettingsService } from '../setting/settings.service.js';
import { InvoiceGeneration } from '../setting/dto/update-settings.dto.js';
import { ContractService } from '../contract/contract.service.js';

@Processor('scheduler_billing_queue')
export class BillingService {
    private static readonly logger = new Logger(BillingService.name);
    constructor(
        @Inject(forwardRef(() => InfluxService)) readonly InfluxService: InfluxService,
        @Inject(forwardRef(() => CustomerService)) readonly customerService: CustomerService,
        @Inject(forwardRef(() => ContractService)) readonly contractService: ContractService,
        @Inject(forwardRef(() => InvoicesService)) readonly invoicesService: InvoicesService,
        @Inject(forwardRef(() => SchedulerService)) readonly schedulerService: SchedulerService,
        @Inject(forwardRef(() => SettingsService)) readonly settingsService: SettingsService,
    ) {}
    @Process({ name: billingScheduleConsumers.billingReport })
    async create({ data: { scheduleParameters, businessID } }: Job<SchedulerEntity>) {
        const { customerId, freeTrialEnd, startDateOverride, endDateOverride, offeringId } =
            scheduleParameters as CreateBillingReportDto;
        BillingService.logger.log(
            `Starting billing report for customer: ${customerId}, Current Time is: ${new Date()}`,
        );
        let setBusinessID = businessID;
        if (!setBusinessID) {
            // change the type of scheduleParameters to CreateBillingReportDto
            const { businessID: schedulerParametersBusinessID } = scheduleParameters as CreateBillingReportDto;
            setBusinessID = schedulerParametersBusinessID;
        }
        try {
            const { data } = await this.customerService.findOne({ businessID: setBusinessID, customerId });
            let offering;
            let startTime;
            let endTime;
            let settingsEntity;
            if (data[0]?.offeringIds && data[0]?.offeringIds.length > 0) {
                const offeringIds = data[0]?.offeringIds;
                const { offering: foundOffering } = await this.contractService.findOne({
                    customerId,
                    businessID: setBusinessID,
                    offeringId: offeringId ? offeringId : offeringIds[offeringIds.length - 1],
                    offeringEnrollmentDate: data[0]?.offeringEnrollmentDate,
                    freeTrialEndDate: data[0]?.freeTrialEndDate,
                });
                offering = foundOffering;
                const { startTime: calcStartTime, endTime: calcEndTime } = Billing.billingCycleToTimeRange(
                    offering.billingCycle,
                );
                startTime = calcStartTime;
                endTime = calcEndTime;
                const [settingsRes] = await this.settingsService.findAll({ businessID: setBusinessID });
                settingsEntity = settingsRes;
            }

            BillingService.logger.log(
                `Processing billing with the following parameters: startDateOverride: ${startDateOverride}, endDateOverride: ${endDateOverride}, freeTrialEnd: ${freeTrialEnd}`,
            );
            let invoiceId;
            if (freeTrialEnd) {
                BillingService.logger.log(`Processing free trial end for customer: ${customerId}`);
                invoiceId = await offering.processFreeTrialEnd({ customer: data[0] });
            } else {
                if (settingsEntity?.invoiceGeneration === InvoiceGeneration.consolidatedPerBillingCycle) {
                    offering.consolidatedInvoice = true;
                }
                invoiceId = await offering.processBilling(
                    startDateOverride ? new Date(startDateOverride) : undefined,
                    endDateOverride ? new Date(endDateOverride) : undefined,
                    data[0],
                    true,
                );
            }

            const entity = new Billing({
                invoiceId,
                businessID: setBusinessID,
                customerId,
                startTime,
                endTime,
                billingId: randomUUID(),
            });
            // 6. Save Billing information to the Ledger
            const point = Billing.transformer(entity, this.InfluxService);
            await this.InfluxService.loadPoints(`${process.env.STAGE}-aggregate-usage`, process.env.INFLUX_ORG, [
                point,
            ]);
            BillingService.logger.log(`Finished billing report for customer: ${customerId}, invoiceId: ${invoiceId}`);
        } catch (error) {
            AuditService.publishEvent({
                message: 'Failed to create billing Invoice',
                topic: AuditScope.ERROR,
                data: [{ error: serializeError(error), customerId, businessID: setBusinessID }],
            });
        }
    }
}
import { Logger } from '@nestjs/common';
import { AuditService } from '../../audit/audit.service.js';
import { AuditScope } from '../../audit/entities/audit.interface.js';
import { AggregatedUsageResponse } from '../../customer/dto/read-customer.dto.js';
import { overageAllowedEnum } from '../../dimensions/dto/create-dimension.dto.js';
import { ReadDimensionResponseData } from 'dimensions/dto/create-dimension.dto.js';
import { InfluxService } from '../../influx/influx.service.js';
import { ValidBillingCycles } from '../../offering/dto/createOffering.dto.js';
import { Offering, Subscription } from '../../offering/entities/offeringPackage.entity.js';
import { FreeDimensionOnInvoice } from '../../setting/dto/FreeDimensionOnInvoice.js';
import { DatetimeUtils } from '../../utils/datetime.js';

export enum billingScheduleConsumers {
    billingReport = 'billingReport',
}

export class Billing {
    private static readonly logger = new Logger(Billing.name);
    public static _measurement = 'billingReport';
    public invoiceId: string;
    public businessID: string;
    public customerId: string;
    public startTime: string;
    public endTime: string;
    public billingId: string;
    constructor({ invoiceId, businessID, customerId, startTime, endTime, billingId }: Billing) {
        this.invoiceId = invoiceId;
        this.businessID = businessID;
        this.customerId = customerId;
        this.startTime = startTime;
        this.endTime = endTime;
        this.billingId = billingId;
    }

    public static billingCycleToTimeRange(billingCycle: ValidBillingCycles): {
        startTime: string;
        endTime: string;
        subscriptionStart: string;
        subscriptionEnd: string;
        currentBillingCycleStartTime: string;
        currentBillingCycleEndTime: string;
    } {
        if (billingCycle === ValidBillingCycles.monthly) {
            return {
                startTime: DatetimeUtils.beginningOfDay(DatetimeUtils.firstDayOfLastMonth()).toISOString(),
                endTime: DatetimeUtils.endOfDay(DatetimeUtils.lastDayOfLastMonth()).toISOString(),
                subscriptionStart: DatetimeUtils.beginningOfDay(DatetimeUtils.firstDayOfMonth()).toISOString(),
                subscriptionEnd: DatetimeUtils.endOfDay(DatetimeUtils.lastDayOfMonth()).toISOString(),
                currentBillingCycleStartTime: DatetimeUtils.beginningOfDay(
                    DatetimeUtils.firstDayOfMonth(),
                ).toISOString(),
                currentBillingCycleEndTime: DatetimeUtils.endOfDay(DatetimeUtils.lastDayOfMonth()).toISOString(),
            };
        }
        if (billingCycle === ValidBillingCycles.annualToDate) {
            return {
                startTime: DatetimeUtils.beginningOfDay(DatetimeUtils.lastYearGivenDate(new Date())).toISOString(),
                endTime: DatetimeUtils.endOfDay(DatetimeUtils.yesterday()).toISOString(),
                subscriptionStart: DatetimeUtils.beginningOfDay(new Date()).toISOString(),
                subscriptionEnd: DatetimeUtils.beginningOfDay(DatetimeUtils.nextYear()).toISOString(),
                currentBillingCycleStartTime: DatetimeUtils.beginningOfDay(new Date()).toISOString(),
                currentBillingCycleEndTime: DatetimeUtils.beginningOfDay(DatetimeUtils.nextYear()).toISOString(),
            };
        }
    }

    public static transformer(billingEntity: Billing, influxService: InfluxService) {
        const billingEntityPoint = influxService.getPoint(Billing._measurement);

        billingEntityPoint.stringField('billingId', billingEntity.billingId);
        billingEntityPoint.tag('billingId', billingEntity.billingId);
        billingEntityPoint.tag('invoiceId', billingEntity.invoiceId);
        billingEntityPoint.tag('businessID', billingEntity.businessID);
        billingEntityPoint.tag('customerId', billingEntity.customerId);
        billingEntityPoint.tag('startTime', billingEntity.startTime);
        billingEntityPoint.tag('endTime', billingEntity.endTime);

        return billingEntityPoint;
    }

    public static dbModelToEntity(dbModel) {
        return new Billing({
            invoiceId: dbModel.invoiceId,
            businessID: dbModel.businessID,
            customerId: dbModel.customerId,
            startTime: dbModel.startTime,
            endTime: dbModel.endTime,
            billingId: dbModel.billingId,
        });
    }

    public static usageToTotal(
        aggregatedUsageResponse: AggregatedUsageResponse,
        dimension: ReadDimensionResponseData,
    ): string {
        try {
            const { usage, dimensionId } = aggregatedUsageResponse;
            if (dimensionId !== dimension?.dimensionId) {
                throw new Error(
                    `dimensionId for usage data: ${dimensionId} does not match dimensionId on dimension document ${dimension?.dimensionId}`,
                );
            }
            const { usageEntitlement, overageAllowed } = dimension;
            const totalUsage = usage.reduce((acc, { value }) => {
                acc += parseFloat(value);
                return acc;
            }, 0);

            if (!usageEntitlement) {
                const usage = totalUsage;
                return usage.toFixed(2).toString();
            }

            if (usageEntitlement === 'inf') {
                return '0.00';
            } else {
                const usageEntitlementValue = parseFloat(usageEntitlement ? usageEntitlement.toString() : '0');
                const usage = totalUsage - usageEntitlementValue;
                if (usage > 0) {
                    if (
                        overageAllowed !== overageAllowedEnum.false ||
                        overageAllowed === undefined ||
                        overageAllowed === null
                    ) {
                        return usage.toFixed(2).toString();
                    } else {
                        return '0.00';
                    }
                } else {
                    return '0.00';
                }
            }
        } catch (e) {
            Billing.logger.error('error in usageToTotal', e);
            AuditService.publishEvent({ message: 'error in usageToTotal', data: [e], topic: AuditScope.ERROR });
        }
    }

    public static determineIfLineItemShown({
        totalUsage,
        dimension,
        Offering,
        unitCost,
        freeDimensionOnInvoice,
    }: {
        totalUsage: number;
        dimension: ReadDimensionResponseData;
        Offering: Offering;
        unitCost: number;
        freeDimensionOnInvoice: FreeDimensionOnInvoice;
    }): boolean {
        try {
            const { usageEntitlement, overageAllowed } = dimension;
            if (unitCost === 0 && freeDimensionOnInvoice === FreeDimensionOnInvoice.hide) {
                return false;
            }

            if (Offering instanceof Subscription) {
                // For subscription based offerings
                if (usageEntitlement === undefined && totalUsage > 0) {
                    return true;
                }
                if (usageEntitlement !== undefined) {
                    // If there is entitlement and overage is allowed, show the line item only if there is usage.
                    if (overageAllowed === overageAllowedEnum.true) {
                        if (usageEntitlement === 'inf') {
                            return false;
                        } else {
                            if (totalUsage > 0) {
                                return true;
                            } else {
                                return false;
                            }
                        }
                    } else {
                        // Entitlement without overage, no line item
                        return false;
                    }
                }
            } else {
                // For usage based offerings
                // If there is no usageEntitlement and there is usage, show the line item
                if (usageEntitlement === undefined && totalUsage > 0) {
                    return true;
                }

                if (usageEntitlement !== undefined) {
                    // If there is usageEntitlement and overage is allowed, show the line item.
                    if (overageAllowed === overageAllowedEnum.true) {
                        return true;
                    } else {
                        // Entitlement without overage, no line item
                        return false;
                    }
                } else {
                    // Zero usage, no usageEntitlement means no line item.
                    return false;
                }
            }
        } catch (e) {
            AuditService.publishEvent({ message: 'error in line item', data: [e], topic: AuditScope.ERROR });
            throw e;
        }
    }
}
