/**
 * Top up offerings are evaluated for the whole offering rather than for a single customer.
 * As such the schedulerID is stable for the offering, and does not contain any customer information.
 */
public static getTopUpSchedulerID(offeringId: string): string {
    return offeringId;
}

/**
 * Determines if the offering is a prepaid credit top up offering
 */
public isTopUp(): boolean {
    return this.billingCycle === ValidBillingCycles.topUp;
}

/**
 * The balance a customers wallet must fall below in order for a top up to occur.
 */
public getTopUpThresholdAmount(): number {
    const topUpAmount = parseFloat(this.topUpAmount);
    const topUpThreshold = parseFloat(
        this.topUpThreshold !== undefined && this.topUpThreshold !== null
            ? this.topUpThreshold
            : DEFAULT_TOP_UP_THRESHOLD,
    );
    return topUpAmount * topUpThreshold;
}

/**
 * Determines the current wallet (credit) balance for a customer.
 * The balance stored on the customer object is used when it is available, this enables the
 * in memory balance to be kept up to date between the usage deduction and the top up evaluation.
 */
public async getWalletBalance(customer?: ReadCustomerResponseData): Promise<number> {
    if (customer?.creditBalance !== undefined && customer?.creditBalance !== null) {
        const parsedBalance = parseFloat(customer.creditBalance as unknown as string);
        if (!isNaN(parsedBalance)) {
            return parsedBalance;
        }
    }
    if (this.creditService) {
        const { balance } = await this.creditService.findCreditBalance({
            businessID: this.businessID,
            customerId: customer?.customerId ? customer?.customerId : this.customerId,
        });
        const parsedBalance = parseFloat(balance);
        return isNaN(parsedBalance) ? 0 : parsedBalance;
    }
    return 0;
}

/**
 * Tops up the customers wallet when the balance has fallen below the top up threshold.
 * The customer is charged exactly the difference between their current balance and the `topUpAmount`.
 * The payment of the created invoice is stored as credit in the customers wallet.
 */
public async topUp({ customer }: { customer?: ReadCustomerResponseData }): Promise<string | void> {
    if (!this.topUpAmount) {
        Offering.logger.warn(
            `Unable to top up offering ${this.offeringName} for customer ${
                customer?.customerId ? customer?.customerId : this.customerId
            }. No topUpAmount is configured`,
        );
        return;
    }
    const topUpAmount = parseFloat(this.topUpAmount);
    if (isNaN(topUpAmount)) {
        return;
    }
    const balance = await this.getWalletBalance(customer);
    const threshold = this.getTopUpThresholdAmount();
    Offering.logger.log(
        `Evaluating top up for ${this.offeringName}. Balance: ${balance}, threshold: ${threshold}, topUpAmount: ${topUpAmount}`,
    );
    if (balance >= threshold) {
        // A balance which sits exactly on the threshold is considered to be sufficient
        return;
    }
    const amountToCharge = Number((topUpAmount - balance).toFixed(2));
    const lineItems = new InvoiceLineItems();
    lineItems.addLineItem(new InvoiceLineItem(`${this.offeringName} - Top Up`, 1, amountToCharge));
    const { invoiceId } = await this.invoicesService.create({
        businessID: this.businessID,
        customerId: customer?.customerId ? customer?.customerId : this.customerId,
        customer,
        items: lineItems,
        invoiceDate: new Date().toISOString(),
        currency: Offering.getCurrency({ customer, offering: this }),
        storePaymentAsCredit: true,
    });
    return invoiceId;
}

