/**
 * Deducts the usage which has occurred in the given time range from the customers wallet,
 * and then evaluates if the wallet needs to be topped up.
 *
 * No usage invoice is generated for prepaid credit offerings, the usage is instead taken directly out of
 * the customers wallet, even in the case where the usage is larger than the remaining balance.
 */
async processTopUpBilling({
    startDate: startDateOverride,
    endDate: endDateOverride,
    customer,
}: {
    startDate?: Date;
    endDate?: Date;
    customer?: ReadCustomerResponseData;
}): Promise<string | void> {
    const { startTime, endTime } = Billing.billingCycleToTimeRange(this.billingCycle);
    const startDate = startDateOverride ? startDateOverride : new Date(startTime);
    const endDate = endDateOverride ? endDateOverride : new Date(endTime);
    const lineItems = new InvoiceLineItems();
    await Offering.getLineItemsForUsage({
        startDate,
        endDate,
        customer,
        lineItems,
        negative: false,
        businessID: this.businessID,
        customerId: this.customerId,
        customerService: this.customerService,
        offeringInstance: this,
        dimensions: this.dimensions,
    });
    const usageTotal = Number(lineItems.getTotal().toFixed(2));
    const customerId = customer?.customerId ? customer?.customerId : this.customerId;
    UsageBased.logger.log(
        `Processing top up billing for ${
            this.offeringName
        } for customer ${customerId} from ${startDate.toISOString()} to ${endDate.toISOString()}. Usage total: ${usageTotal}`,
    );
    if (usageTotal > 0) {
        const balance = await this.getWalletBalance(customer);
        if (this.creditService) {
            await this.creditService.create({
                transactionAmount: (usageTotal * -1).toFixed(2),
                customerId,
                businessID: this.businessID,
                timestamp: new Date().toISOString(),
                allowNegativeBalance: true,
                metadata: {
                    offeringId: this.offeringId,
                    reason: `Usage for ${this.offeringName}`,
                },
            });
        } else {
            UsageBased.logger.warn(
                `Unable to deduct usage from the wallet of customer ${customerId}, no credit service is available`,
            );
        }
        // Keep the in memory balance up to date so that the top up evaluation uses the new balance
        if (customer) {
            customer.creditBalance = Number((balance - usageTotal).toFixed(2)).toString();
        }
    }
    return this.topUp({ customer });
}

