async unenroll({ customer, isChangeOfPlan }): Promise<void> {
    if (this.isTopUp()) {
        // Prepaid credit offerings do not generate an invoice on unenrollment, the customers
        // remaining wallet balance is left untouched.
        UsageBased.logger.debug(
            `Running Unenrollment for Customer: ${customer?.customerId} from top up offering ${this.offeringName}`,
        );
        await this.deregisterBillingSchedule();
        return;
    }
    const { currentBillingCycleStartTime } = Billing.billingCycleToTimeRange(this.billingCycle);

    if (billingCycle === ValidBillingCycles.annualToDate) {
        return {
            startTime: DatetimeUtils.beginningOfDay(DatetimeUtils.lastYearGivenDate(new Date())).toISOString(),
            endTime: DatetimeUtils.endOfDay(DatetimeUtils.yesterday()).toISOString(),
            subscriptionStart: DatetimeUtils.beginningOfDay(new Date()).toISOString(),
            subscriptionEnd: DatetimeUtils.beginningOfDay(DatetimeUtils.nextYear()).toISOString(),
            currentBillingCycleStartTime: DatetimeUtils.beginningOfDay(new Date()).toISOString(),
            currentBillingCycleEndTime: DatetimeUtils.beginningOfDay(DatetimeUtils.nextYear()).toISOString(),
        };
    }
    if (billingCycle === ValidBillingCycles.topUp) {
        // Prepaid credit offerings are evaluated every hour, as such the billing cycle is the last hour
        const now = new Date();
        const oneHourAgo = new Date(now.getTime() - MILLISECONDS_IN_AN_HOUR);
        return {
            startTime: oneHourAgo.toISOString(),
            endTime: now.toISOString(),
            subscriptionStart: oneHourAgo.toISOString(),
            subscriptionEnd: now.toISOString(),
            currentBillingCycleStartTime: oneHourAgo.toISOString(),
