/**
 * Validates the prepaid credit top up configuration of an offering.
 *  - A top up amount is required when the billing cycle is `topUp`
 *  - Top up fields are only valid on offerings with a `topUp` billing cycle
 *  - Subscription offerings cannot be billed through prepaid credit top ups
 */
static validateTopUpFields({
    billingCycle,
    offeringType,
    topUpAmount,
    topUpThreshold,
}: {
    billingCycle?: ValidBillingCycles;
    offeringType?: string;
    topUpAmount?: string;
    topUpThreshold?: string;
}): void {
    if (billingCycle === ValidBillingCycles.topUp) {
        if (offeringType === OfferingType.subscription) {
            throw new BadRequestException('Subscription offerings cannot use the topUp billing cycle');
        }
        if (!topUpAmount) {
            throw new BadRequestException('A topUpAmount is required for offerings with a topUp billing cycle');
        }
    } else if (topUpAmount || topUpThreshold) {
        throw new BadRequestException(
            'topUpAmount and topUpThreshold are only allowed on offerings with a topUp billing cycle',
        );
    }
}

