import { IsNotEmpty, IsString } from 'class-validator';

/**
 * The scheduler parameters used by the hourly prepaid credit top up check.
 * The check is registered once per offering, as such no customer information is carried in the parameters.
 */
export class OfferingTopUpCheckerDto {
    /**
     * The unique identifier of the offering which is being evaluated
     */
    @IsString()
    @IsNotEmpty()
    public offeringId: string;

    /**
     * The unique identifier for the SaaS business
     */
    @IsString()
    @IsNotEmpty()
    public businessID: string;
}

import { Inject, Injectable, Logger, forwardRef } from '@nestjs/common';
import { serializeError } from 'serialize-error';
import { AuditService } from '../../audit/audit.service.js';
import { AuditScope } from '../../audit/entities/audit.interface.js';
import { ContractService } from '../../contract/contract.service.js';
import { CustomerService } from '../../customer/customer.service.js';
import { ReadCustomerResponseData } from '../../customer/entities/customer.entity.js';
import { Offering } from '../../offering/entities/offeringPackage.entity.js';
import { OfferingTopUpCheckerDto } from './dto/offeringTopUpChecker.dto.js';

/**
 * Evaluates every customer enrolled in a prepaid credit (`topUp`) offering.
 *
 * For each customer the usage which occurred within the last hour is deducted from the customers wallet,
 * and the wallet is topped up when the remaining balance has fallen below the top up threshold.
 */
@Injectable()
export class OfferingTopUpChecker {
    private static readonly logger = new Logger(OfferingTopUpChecker.name);
    constructor(
        @Inject(forwardRef(() => CustomerService)) readonly customerService: CustomerService,
        @Inject(forwardRef(() => ContractService)) readonly contractService: ContractService,
    ) {}

    /**
     * The schedulerID used for the hourly top up check. It is offering level, and therefore stable
     * across every customer enrolled in the offering.
     */
    static getTopUpScheduleId(offeringId: string): string {
        return Offering.getTopUpSchedulerID(offeringId);
    }

    async checkTopUpsForOffering({ businessID, offeringId }: OfferingTopUpCheckerDto): Promise<void> {
        OfferingTopUpChecker.logger.log(
            `Starting prepaid credit top up check for offering: ${offeringId} in business: ${businessID}`,
        );
        let customers: ReadCustomerResponseData[] = [];
        try {
            const { data } = await this.customerService.findAllCustomersWithOfferingId({ businessID, offeringId });
            customers = data ? data : [];
        } catch (error) {
            OfferingTopUpChecker.logger.warn(
                `No customers found for offering: ${offeringId} in business: ${businessID}`,
            );
            return;
        }
        for (const customer of customers) {
            try {
                await this.checkTopUpForCustomer({ businessID, offeringId, customer });
            } catch (error) {
                OfferingTopUpChecker.logger.error(serializeError(error));
                AuditService.publishEvent({
                    message: 'Failed to process prepaid credit top up for customer',
                    topic: AuditScope.ERROR,
                    data: [
                        {
                            error: serializeError(error),
                            customerId: customer?.customerId,
                            businessID,
                            offeringId,
                        },
                    ],
                });
            }
        }
    }

    async checkTopUpForCustomer({
        businessID,
        offeringId,
        customer,
    }: OfferingTopUpCheckerDto & { customer: ReadCustomerResponseData }): Promise<string | void> {
        const { offering } = await this.contractService.findOne({
            businessID,
            offeringId,
            customerId: customer?.customerId,
            offeringEnrollmentDate: customer?.offeringEnrollmentDate,
            freeTrialEndDate: customer?.freeTrialEndDate,
        });
        if (!offering?.isTopUp()) {
            OfferingTopUpChecker.logger.warn(
                `Offering: ${offeringId} in business: ${businessID} is not a prepaid credit top up offering`,
            );
            return;
        }
        // Deducts the last hour of usage from the customers wallet, and then tops the wallet up if required
        return offering.processBilling(undefined, undefined, customer, true);
    }
}

