        jest.spyOn(customerService, 'findUsageForCustomer').mockImplementation(async () => ({
            message: 'fake',
            data: [
                {
                    dimensionId: 'dimensionId',
                    usage: [
                        { startTime: new Date().toISOString(), endTime: new Date().toISOString(), value },
                    ],
                },
            ],
        }));
    };

    it('should be a usage based offering with a topUp billing cycle', () => {
        const offering = buildOffering();
        expect(offering).toBeInstanceOf(UsageBased);
        expect(offering.isTopUp()).toEqual(true);
        expect(offering.topUpAmount).toEqual('100');
        expect(offering.topUpThreshold).toEqual('0.2');
        expect(typeof offering.topUp).toEqual('function');
    });

    it('should default the top up threshold to 0.2', () => {
        const offering = buildOffering({ topUpThreshold: undefined });
        expect(offering.topUpThreshold).toEqual('0.2');
        expect(offering.getTopUpThresholdAmount()).toEqual(20);
    });

    it('should register a single hourly offering level schedule on enrollment', async () => {
        const offering = buildOffering();
        await offering.enroll('fakeSubject', customer);
        expect(schedulerService.create).toHaveBeenCalledTimes(1);
        expect(schedulerService.create).toHaveBeenCalledWith(
            expect.objectContaining({
                schedulerID: fakeOfferingID,
                rate: SupportedMeasurementFrequencies.everyHour,
                scheduleParameters: { businessID: fakeBusinessID, offeringId: fakeOfferingID },
            }),
        );
        const [[{ scheduleParameters, schedulerID }]] = (schedulerService.create as jest.Mock).mock.calls;
        expect(schedulerID).not.toContain(fakeCustomerID);
        expect(scheduleParameters).not.toHaveProperty('customerId');
    });

    it('should top up the wallet on enrollment', async () => {
        const offering = buildOffering();
        await offering.enroll('fakeSubject', customer);
        expect(invoicesService.create).toHaveBeenCalledTimes(1);
        const [[invoiceInput]] = (invoicesService.create as jest.Mock).mock.calls;
        expect(invoiceInput.storePaymentAsCredit).toEqual(true);
        expect((invoiceInput.items as InvoiceLineItems).getLineItems()).toEqual([
            { name: 'Top Up Plan - Top Up', quantity: 1, unitCost: 100, description: undefined },
        ]);
    });

    it('should not top up the wallet when the balance sits exactly on the threshold', async () => {
        const offering = buildOffering();
        await offering.topUp({ customer: { ...customer, creditBalance: '20' } });
        expect(invoicesService.create).not.toHaveBeenCalled();
    });

    it('should top up the wallet for the gap when the balance is below the threshold', async () => {
        const offering = buildOffering();
        await offering.topUp({ customer: { ...customer, creditBalance: '19.50' } });
        expect(invoicesService.create).toHaveBeenCalledTimes(1);
        const [[invoiceInput]] = (invoicesService.create as jest.Mock).mock.calls;
        expect(invoiceInput.storePaymentAsCredit).toEqual(true);
        expect((invoiceInput.items as InvoiceLineItems).getLineItems()).toEqual([
            { name: 'Top Up Plan - Top Up', quantity: 1, unitCost: 80.5, description: undefined },
        ]);
    });

    it('should deduct hourly usage from the wallet without creating a usage invoice', async () => {
        mockUsage('30');
        const offering = buildOffering();
        await offering.processBilling(undefined, undefined, { ...customer, creditBalance: '100' }, true);
        expect(creditService.create).toHaveBeenCalledTimes(1);
        expect(creditService.create).toHaveBeenCalledWith(
            expect.objectContaining({
                transactionAmount: '-30.00',
                customerId: fakeCustomerID,
                businessID: fakeBusinessID,
            }),
        );
        // 100 - 30 = 70 which is above the threshold of 20, no invoice should be created
        expect(invoicesService.create).not.toHaveBeenCalled();
    });

    it('should evaluate the top up using the balance after the usage deduction', async () => {
        mockUsage('90');
        const offering = buildOffering();
        const customerWithBalance = { ...customer, creditBalance: '100' };
        await offering.processBilling(undefined, undefined, customerWithBalance, true);
        expect(creditService.create).toHaveBeenCalledWith(
            expect.objectContaining({ transactionAmount: '-90.00' }),
        );
        expect(customerWithBalance.creditBalance).toEqual('10');
        expect(invoicesService.create).toHaveBeenCalledTimes(1);
        const [[invoiceInput]] = (invoicesService.create as jest.Mock).mock.calls;
        expect((invoiceInput.items as InvoiceLineItems).getLineItems()).toEqual([
            { name: 'Top Up Plan - Top Up', quantity: 1, unitCost: 90, description: undefined },
        ]);
    });

    it('should deduct usage which is larger than the current balance', async () => {
        mockUsage('150');
        const offering = buildOffering();
        const customerWithBalance = { ...customer, creditBalance: '100' };
        await offering.processBilling(undefined, undefined, customerWithBalance, true);
        expect(creditService.create).toHaveBeenCalledWith(
            expect.objectContaining({ transactionAmount: '-150.00', allowNegativeBalance: true }),
        );
        expect(customerWithBalance.creditBalance).toEqual('-50');
        const [[invoiceInput]] = (invoicesService.create as jest.Mock).mock.calls;
        expect((invoiceInput.items as InvoiceLineItems).getLineItems()).toEqual([
            { name: 'Top Up Plan - Top Up', quantity: 1, unitCost: 150, description: undefined },
        ]);
    });

    it('should not create a wallet transaction when there is no usage', async () => {
        const offering = buildOffering();
        await offering.processBilling(undefined, undefined, { ...customer, creditBalance: '5' }, true);
        expect(creditService.create).not.toHaveBeenCalled();
        expect(invoicesService.create).toHaveBeenCalledTimes(1);
        const [[invoiceInput]] = (invoicesService.create as jest.Mock).mock.calls;
        expect((invoiceInput.items as InvoiceLineItems).getLineItems()).toEqual([
            { name: 'Top Up Plan - Top Up', quantity: 1, unitCost: 95, description: undefined },
        ]);
    });

    it('should read the balance from the wallet when the customer does not carry one', async () => {
        jest.spyOn(creditService, 'findCreditBalance').mockImplementation(async () => ({
            balance: '50',
            customerId: fakeCustomerID,
            message: 'found',
        }));
        const offering = buildOffering();
        await offering.topUp({ customer });
        expect(invoicesService.create).not.toHaveBeenCalled();
    });

    it('should not remove the offering level schedule when a single customer unenrolls', async () => {
        const offering = buildOffering();
        await offering.unenroll({ customer, isChangeOfPlan: false });
        expect(schedulerService.remove).not.toHaveBeenCalled();
        expect(invoicesService.create).not.toHaveBeenCalled();
    });
});

