import { createMock } from '@golevelup/ts-jest';
import { ContractService } from '../../contract/contract.service.js';
import { CustomerService } from '../../customer/customer.service.js';
import { ReadCustomerResponseData } from '../../customer/entities/customer.entity.js';
import { Offering } from '../../offering/entities/offeringPackage.entity.js';
import { OfferingTopUpChecker } from './offeringTopUpChecker.service.js';

describe('OfferingTopUpChecker', () => {
    const businessID = 'fakeBusinessID';
    const offeringId = 'fakeOfferingID';
    let customerService: CustomerService;
    let contractService: ContractService;
    let checker: OfferingTopUpChecker;
    const processBilling = jest.fn();
    const customers = [
        { customerId: 'customerOne', businessID } as ReadCustomerResponseData,
        { customerId: 'customerTwo', businessID } as ReadCustomerResponseData,
    ];

    beforeEach(() => {
        customerService = createMock<CustomerService>({
            //eslint-disable-next-line
            //@ts-ignore
            findAllCustomersWithOfferingId: jest.fn(async () => ({ data: customers, message: 'Found Customers' })),
        });
        contractService = createMock<ContractService>({
            //eslint-disable-next-line
            //@ts-ignore
            findOne: jest.fn(async () => ({
                offering: {
                    isTopUp: () => true,
                    processBilling,
                } as unknown as Offering,
            })),
        });
        checker = new OfferingTopUpChecker(customerService, contractService);
    });

    afterEach(() => {
        jest.clearAllMocks();
    });

    it('should evaluate every customer enrolled in the offering', async () => {
        await checker.checkTopUpsForOffering({ businessID, offeringId });
        expect(customerService.findAllCustomersWithOfferingId).toHaveBeenCalledWith({ businessID, offeringId });
        expect(processBilling).toHaveBeenCalledTimes(2);
        expect(processBilling).toHaveBeenCalledWith(undefined, undefined, customers[0], true);
        expect(processBilling).toHaveBeenCalledWith(undefined, undefined, customers[1], true);
    });

    it('should keep evaluating customers when one of them fails', async () => {
        processBilling.mockRejectedValueOnce(new Error('failed'));
        await expect(checker.checkTopUpsForOffering({ businessID, offeringId })).resolves.toBeUndefined();
        expect(processBilling).toHaveBeenCalledTimes(2);
    });

    it('should not process offerings which are not top up offerings', async () => {
        //eslint-disable-next-line
        //@ts-ignore
        jest.spyOn(contractService, 'findOne').mockImplementation(async () => ({
            offering: { isTopUp: () => false, processBilling } as unknown as Offering,
        }));
        await checker.checkTopUpsForOffering({ businessID, offeringId });
        expect(processBilling).not.toHaveBeenCalled();
    });

    it('should use a stable offering level schedule id', () => {
        expect(OfferingTopUpChecker.getTopUpScheduleId(offeringId)).toEqual(
            Offering.getTopUpSchedulerID(offeringId),
        );
        expect(OfferingTopUpChecker.getTopUpScheduleId(offeringId)).not.toContain('customer');
    });
});

